
// Draws winners from lotteries whose end dates have passed, and notifies the winners and losers

/*
* NOTE: Generated by Claude Opus 5.5, 2026/11/23
*
* Q: "We are building an app in Android Studio, where campsite owners can post lotteries for their campsites, and users can sign up and reserve these campsites.
*     We want the system to automatically draw winners and notify them at the end of the lottery dates. However, we are using firebase. This is for a school project,
*     and they advised us not to use credit card information for anything, and so we can't sign up for cloud services with firebase. How can we get around this without
*     having the application manually check for ended lotteries and notifying the winners whenever a lottery is loaded in app?"
*
* Q: "Can we generate the script for Kotlin rather than node.js?"
*
* Q: "Please generate KDocs for the updated file Draw.kt file"
*
* Note: did not have access to firebase or project scheme, so many changes were made from the original.
*/

/**
 * Draws winners for every lottery whose end date has passed and notifies everyone who entered.
 *
 * Run every hour by the `draw-lotteries` GitHub Actions workflow
 * (`.github/workflows/draw.yml`), or locally with `./gradlew run`.
 *
 * ## Environment
 * Requires the `FIREBASE_SERVICE_ACCOUNT` environment variable to contain the full JSON of a
 * Firebase service account key. On GitHub, this comes from the repository secret of the same name.
 * The script logs in with admin access, so Firestore security rules do not apply to it.
 *
 * Obtains lists of lotteries past end date that have not been drawn, creates winners list and losers list,
 * updates selectedlist to winners list, and updates drawn to true, then creates winners and losers notifications
 *
 * All writes for a lottery happen in one transaction, so a lottery is either drawn completely,
 * with its notifications, or left unchanged and retried on the next run.
 *
 * Lotteries without a `drawn` field never match the query, so the app must set
 * `drawn = false` when it creates a lottery.
 *
 * @throws IllegalStateException if `FIREBASE_SERVICE_ACCOUNT` is not set.
 * @throws java.util.concurrent.ExecutionException if a Firestore request fails, for example
 *   because the required index is missing. The program then exits with a non-zero code,
 *   which marks the GitHub Actions run as failed.
 */

import com.google.auth.oauth2.GoogleCredentials
import com.google.cloud.Timestamp
import com.google.cloud.firestore.DocumentSnapshot
import com.google.cloud.firestore.FieldValue
import com.google.firebase.FirebaseApp
import com.google.firebase.FirebaseOptions
import com.google.firebase.cloud.FirestoreClient
import java.security.SecureRandom
import kotlin.random.asKotlinRandom
import kotlin.system.exitProcess

fun main() {
    val json = System.getenv("FIREBASE_SERVICE_ACCOUNT")
        ?: error("FIREBASE_SERVICE_ACCOUNT is not set")

    // Initialize with firebase key
    FirebaseApp.initializeApp(
        FirebaseOptions.builder()
            .setCredentials(GoogleCredentials.fromStream(json.byteInputStream()))
            .build()
    )
    val db = FirestoreClient.getFirestore()
    val random = SecureRandom().asKotlinRandom() // random selection
    val now = Timestamp.now()

    // eligible lotteries to draw
    val due = db.collection("Lotteries")
        .whereEqualTo("drawn", false) // only lotteries that haven't drawn yet
        .whereLessThanOrEqualTo("end", now)
        .get().get()

    for (lot in due.documents) {
        db.runTransaction { tx ->
            val snap = tx.get(lot.reference).get()
            if (snap.getBoolean("drawn") != false) return@runTransaction null // already drawn

            val waitlist = snap.stringList("waitlist") // waitlist is array of profile ids
            val spots = snap.getLong("lotteryWinners")?.toInt() ?: 0
            val winners = waitlist.shuffled(random).take(spots)

            val winnerSet = winners.toSet()
            val losers = waitlist.filter { it !in winnerSet }
            val title = snap.getString("title") ?: "a lottery"

            // set lottery drawn to true and add winners to selected list
            tx.update(lot.reference, mapOf("selectedlist" to winners, "drawn" to true,))

            // NOTIFICATION: create winners notification
            if(winners.isNotEmpty()){
                tx.create(db.collection("Notifications").document(), mapOf(
                    "lotteryId" to lot.id,
                    "message" to "You were selected for ${title}. Please click this notification " +
                            "to select your dates, campsite (if applicable), and make a reservation!",
                    "recipientIds" to winners,
                    "reservationId" to "",
                    "senderId" to "",
                    "subject" to "You won a lottery!",
                    "timestamp" to FieldValue.serverTimestamp(),
                    "type" to "wonLottery",
                    "viewedBy" to emptyList<String>()
                ))
            }

            // NOTIFICATION: create losers notification
            if (losers.isNotEmpty()) {
                tx.create(db.collection("Notifications").document(), mapOf(
                    "lotteryId" to lot.id,
                    "message" to "Unfortunately, you were not selected for ${title}.",
                    "recipientIds" to losers,
                    "reservationId" to "",
                    "senderId" to "",
                    "subject" to "You lost a lottery",
                    "timestamp" to FieldValue.serverTimestamp(),
                    "type" to "lostLottery",
                    "viewedBy" to emptyList<String>()
                ))
            }
            null
        }.get()
    }

    exitProcess(0) // Firebase keeps background threads alive, so exit explicitly
}

/** Reads a Firestore string array as a List<String>, or an empty list if the field is missing. */
private fun DocumentSnapshot.stringList(field: String): List<String> =
    (get(field) as? List<*>)?.filterIsInstance<String>() ?: emptyList()
